  1→import {
  2→  Controller,
  3→  Post,
  4→  Get,
  5→  Body,
  6→  HttpCode,
  7→  HttpStatus,
  8→  UseGuards,
  9→  Request,
 10→  Res,
 11→  Req,
 12→  UnauthorizedException,
 13→} from '@nestjs/common';
 14→import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth } from '@nestjs/swagger';
 15→import { Response, Request as ExpressRequest } from 'express';
 16→import { AuthService } from './auth.service';
 17→import { LoginDto, LoginResponseDto } from './dto/login.dto';
 18→import { TokenResponseDto, DesktopRefreshDto, LogoutResponseDto } from './dto/token.dto';
 19→import { TestLoginDto, TestLoginResponseDto } from './dto/test-login.dto';
 20→import {
 21→  LinkMethodDto,
 22→  AuthMethodResponseDto,
 23→  UnlinkMethodDto,
 24→  UnlinkMethodResponseDto,
 25→} from './dto/link-method.dto';
 26→import { ThrottlerGuard } from '@nestjs/throttler';
 27→import { Throttle } from '@nestjs/throttler';
 28→import { JwtAuthGuard } from './guards/jwt-auth.guard';
 29→import { User } from './entities/user.entity';
 30→import { MetricsService } from '../metrics/metrics.service';
 31→
 32→interface RequestWithUser extends Request {
 33→  user: User;
 34→}
 35→
 36→// Cookie configuration
 37→const REFRESH_TOKEN_COOKIE_OPTIONS = {
 38→  httpOnly: true,
 39→  secure: process.env.NODE_ENV === 'production',
 40→  sameSite: 'lax' as const,
 41→  maxAge: 7 * 24 * 60 * 60 * 1000, // 7 days
 42→  path: '/auth', // Only sent to auth endpoints
 43→};
 44→
 45→@ApiTags('Auth')
 46→@Controller('auth')
 47→export class AuthController {
 48→  constructor(
 49→    private authService: AuthService,
 50→    private readonly metricsService: MetricsService
 51→  ) {}
 52→
 53→  @Post('login')
 54→  @HttpCode(HttpStatus.OK)
 55→  @UseGuards(ThrottlerGuard)
 56→  @Throttle({ default: { limit: 10, ttl: 60000 } })
 57→  @ApiOperation({ summary: 'Authenticate user with Web3Auth ID token' })
 58→  @ApiResponse({
 59→    status: 200,
 60→    description: 'Successfully authenticated',
 61→    type: LoginResponseDto,
 62→  })
 63→  @ApiResponse({ status: 401, description: 'Invalid Web3Auth token' })
 64→  async login(
 65→    @Body() loginDto: LoginDto,
 66→    @Req() req: ExpressRequest,
 67→    @Res({ passthrough: true }) res: Response
 68→  ): Promise<LoginResponseDto> {
 69→    const result = await this.authService.login(loginDto);
 70→    this.metricsService.authLogins.inc({
 71→      method: 'web3auth',
 72→      new_user: String(result.isNewUser),
 73→    });
 74→    const isDesktop = req.headers['x-client-type'] === 'desktop';
 75→
 76→    if (isDesktop) {
 77→      // Desktop clients: return refreshToken in response body (no cookie)
 78→      return {
 79→        accessToken: result.accessToken,
 80→        refreshToken: result.refreshToken,
 81→        isNewUser: result.isNewUser,
 82→      };
 83→    }
 84→
 85→    // Web clients: set refresh token in HTTP-only cookie
 86→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
 87→
 88→    return {
 89→      accessToken: result.accessToken,
 90→      isNewUser: result.isNewUser,
 91→    };
 92→  }
 93→
 94→  @Post('refresh')
 95→  @HttpCode(HttpStatus.OK)
 96→  @ApiOperation({ summary: 'Refresh access token using HTTP-only refresh token cookie' })
 97→  @ApiResponse({
 98→    status: 200,
 99→    description: 'Tokens refreshed successfully',
100→    type: TokenResponseDto,
101→  })
102→  @ApiResponse({ status: 401, description: 'Invalid or expired refresh token' })
103→  async refresh(
104→    @Req() req: ExpressRequest,
105→    @Body() body: DesktopRefreshDto,
106→    @Res({ passthrough: true }) res: Response
107→  ): Promise<TokenResponseDto> {
108→    const isDesktop = req.headers['x-client-type'] === 'desktop';
109→
110→    let refreshToken: string | undefined;
111→
112→    if (isDesktop) {
113→      // Desktop clients: read refresh token from request body
114→      refreshToken = body?.refreshToken;
115→    } else {
116→      // Web clients: read refresh token from cookie
117→      refreshToken = req.cookies?.['refresh_token'];
118→    }
119→
120→    if (!refreshToken) {
121→      throw new UnauthorizedException('No refresh token');
122→    }
123→
124→    const result = await this.authService.refreshByToken(refreshToken);
125→
126→    if (isDesktop) {
127→      // Desktop clients: return new refreshToken in response body (no cookie)
128→      return {
129→        accessToken: result.accessToken,
130→        refreshToken: result.refreshToken,
131→        email: result.email,
132→      };
133→    }
134→
135→    // Web clients: set new refresh token in HTTP-only cookie (rotation)
