255→  /**
256→   * Get all linked auth methods for a user.
257→   * Returns identifierDisplay (human-readable) for all method types.
258→   * Falls back to identifier if identifierDisplay is not set.
259→   */
260→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
261→    const methods = await this.authMethodRepository.find({
262→      where: { userId },
263→      order: { createdAt: 'ASC' },
264→    });
265→
266→    return methods.map((method) => ({
267→      id: method.id,
268→      type: method.type,
269→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
270→      identifier: method.identifierDisplay || '[redacted]',
271→      lastUsedAt: method.lastUsedAt,
272→      createdAt: method.createdAt,
273→    }));
274→  }
