 33→/**
 34→ * Settings page wrapped in AppShell.
 35→ * Protected route - redirects to login if not authenticated.
 36→ *
 37→ * Tabs: Linked Methods | Security
 38→ * VaultExport shown below tabs (always visible).
 39→ */
 40→export function SettingsPage() {
 41→  const { isAuthenticated, isLoading } = useAuth();
 42→  const navigate = useNavigate();
 43→  const [activeTab, setActiveTab] = useState<SettingsTabId>('linked-methods');
 44→  const [copied, setCopied] = useState(false);
 45→  const copyTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 46→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 47→
 48→  const publicKeyHex = vaultKeypair?.publicKey ? `0x${bytesToHex(vaultKeypair.publicKey)}` : null;
 49→
 50→  const handleCopyPublicKey = useCallback(() => {
 51→    if (!publicKeyHex) return;
 52→    navigator.clipboard.writeText(publicKeyHex).then(() => {
 53→      setCopied(true);
 54→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 55→      copyTimeoutRef.current = setTimeout(() => setCopied(false), 2000);
 56→    });
 57→  }, [publicKeyHex]);
 58→
 59→  // Clean up timeout on unmount
 60→  useEffect(() => {
 61→    return () => {
 62→      if (copyTimeoutRef.current) clearTimeout(copyTimeoutRef.current);
 63→    };
 64→  }, []);
 65→
 66→  // Redirect if not authenticated
 67→  useEffect(() => {
 68→    if (!isLoading && !isAuthenticated) {
 69→      navigate('/');
 70→    }
 71→  }, [isAuthenticated, isLoading, navigate]);
 72→
 73→  // Show loading state while checking authentication
 74→  if (isLoading) {
 75→    return (
 76→      <AppShell>
 77→        <div className="loading">Loading...</div>
 78→      </AppShell>
 79→    );
 80→  }
 81→
 82→  // Don't render if not authenticated (redirect is in progress)
 83→  if (!isAuthenticated) {
 84→    return null;
 85→  }
 86→
 87→  return (
