  1→import {
  2→  Injectable,
  3→  Logger,
  4→  UnauthorizedException,
  5→  BadRequestException,
  6→  ForbiddenException,
  7→  OnModuleDestroy,
  8→} from '@nestjs/common';
  9→import { InjectRepository } from '@nestjs/typeorm';
 10→import { ConfigService } from '@nestjs/config';
 11→import { Repository, IsNull, Like, Not } from 'typeorm';
 12→import { createECDH, createHash, timingSafeEqual } from 'crypto';
 13→import * as jose from 'jose';
 14→import * as argon2 from 'argon2';
 15→import Redis from 'ioredis';
 16→import { User } from './entities/user.entity';
 17→import { AuthMethod } from './entities/auth-method.entity';
 18→import { RefreshToken } from './entities/refresh-token.entity';
 19→import { JwtIssuerService } from './services/jwt-issuer.service';
 20→import { TokenService } from './services/token.service';
 21→import { SiweService } from './services/siwe.service';
 22→import { parseSiweMessage } from 'viem/siwe';
 23→import { LoginDto, LoginServiceResult } from './dto/login.dto';
 24→import { RefreshServiceResult, LogoutResponseDto } from './dto/token.dto';
 25→import { LinkMethodDto, AuthMethodResponseDto } from './dto/link-method.dto';
 26→
 27→@Injectable()
 28→export class AuthService implements OnModuleDestroy {
 29→  private readonly logger = new Logger(AuthService.name);
 30→  private readonly redis: Redis;
 31→
 32→  constructor(
 33→    private configService: ConfigService,
 34→    private jwtIssuerService: JwtIssuerService,
 35→    private tokenService: TokenService,
 36→    private siweService: SiweService,
 37→    @InjectRepository(User)
 38→    private userRepository: Repository<User>,
 39→    @InjectRepository(AuthMethod)
 40→    private authMethodRepository: Repository<AuthMethod>,
 41→    @InjectRepository(RefreshToken)
 42→    private refreshTokenRepository: Repository<RefreshToken>
 43→  ) {
 44→    this.redis = new Redis({
 45→      host: configService.get('REDIS_HOST', 'localhost'),
 46→      port: configService.get<number>('REDIS_PORT', 6379),
 47→      password: configService.get('REDIS_PASSWORD', undefined),
 48→      lazyConnect: true,
 49→    });
 50→  }
 51→
 52→  async onModuleDestroy(): Promise<void> {
 53→    await this.redis.quit();
 54→  }
 55→
 56→  async login(loginDto: LoginDto): Promise<LoginServiceResult> {
 57→    // 1. Verify CipherBox-issued JWT.
 58→    // All auth methods now go through: CipherBox identity provider -> Core Kit loginWithJWT -> /auth/login.
 59→    const payload = await this.verifyCipherBoxJwt(loginDto.idToken);
 60→
 61→    // 2. Find or create user
 62→    let user = await this.userRepository.findOne({
 63→      where: { publicKey: loginDto.publicKey },
 64→    });
 65→
 66→    // 2b. Placeholder publicKey resolution for Core Kit identity provider.
 67→    // When a user first authenticates via CipherBox identity provider,
 68→    // they get a placeholder publicKey ('pending-core-kit-{userId}').
 69→    // After Core Kit login, the client calls /auth/login with the REAL publicKey.
 70→    // We need to find the placeholder user and update their publicKey.
 71→    if (!user) {
 72→      const verifierId = payload.verifierId || payload.sub;
 73→      if (verifierId) {
 74→        const placeholderUser = await this.userRepository.findOne({
 75→          where: { publicKey: Like(`pending-core-kit-${verifierId}%`) },
 76→        });
 77→        if (placeholderUser) {
 78→          this.logger.log(`Resolving placeholder publicKey for user ${placeholderUser.id}`);
 79→          placeholderUser.publicKey = loginDto.publicKey;
 80→          user = await this.userRepository.save(placeholderUser);
 81→        }
 82→      }
 83→    }
 84→
 85→    const isNewUser = !user;
 86→    if (!user) {
 87→      user = await this.userRepository.save({
 88→        publicKey: loginDto.publicKey,
 89→      });
 90→    }
 91→
 92→    // 3. Find or create auth method
 93→    // The identity controller already created the auth method
 94→    // (with the correct type: 'google', 'email', or 'wallet'). Look up by
 95→    // userId + identifierHash to avoid creating duplicates with a hardcoded type.
 96→    let authMethod: AuthMethod | null;
 97→
 98→    const identifier = payload.email || payload.sub;
 99→    if (!identifier) {
100→      this.logger.warn('CipherBox JWT missing both email and sub claims');
101→      throw new UnauthorizedException('Invalid identity token: missing identifier');
102→    }
103→    const identifierHash = this.siweService.hashIdentifier(identifier);
104→    authMethod = await this.authMethodRepository.findOne({
105→      where: { userId: user.id, identifierHash },
106→    });
107→    if (!authMethod) {
108→      // Fallback: find any auth method for this user (identity controller should have created one)
109→      authMethod = await this.authMethodRepository.findOne({
110→        where: { userId: user.id },
111→      });
112→    }
113→    if (!authMethod) {
114→      // Safety net: create auth method if identity controller didn't (shouldn't happen in practice)
115→      // All logins go through loginType='corekit' now, but infer type from identifier format
116→      const inferredType = identifier.startsWith('0x') ? 'wallet' : 'email';
117→      const display =
118→        inferredType === 'wallet'
119→          ? this.siweService.truncateWalletAddress(identifier)
120→          : this.siweService.truncateEmail(identifier);
121→      authMethod = await this.authMethodRepository.save({
122→        userId: user.id,
123→        type: inferredType,
124→        identifier: identifierHash,
125→        identifierHash,
126→        identifierDisplay: display,
127→      });
128→    }
129→
130→    // 4. Update last used timestamp
131→    authMethod.lastUsedAt = new Date();
132→    await this.authMethodRepository.save(authMethod);
133→
134→    // 5. Create tokens
135→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
136→
137→    return {
138→      accessToken: tokens.accessToken,
139→      refreshToken: tokens.refreshToken,
140→      isNewUser,
141→    };
142→  }
143→
144→  /**
145→   * Verify a CipherBox-issued JWT for Core Kit login flow.
146→   * Since we are the identity provider, we verify against our own JWKS.
147→   */
148→  private async verifyCipherBoxJwt(
149→    idToken: string
150→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
151→    try {
152→      const jwksData = this.jwtIssuerService.getJwksData();
153→      const jwks = jose.createLocalJWKSet(jwksData);
154→      const { payload } = await jose.jwtVerify(idToken, jwks, {
155→        issuer: 'cipherbox',
156→        audience: 'web3auth',
157→        algorithms: ['RS256'],
158→      });
159→      return {
160→        sub: payload.sub,
161→        verifierId: payload.sub,
162→        email: payload.email as string | undefined,
163→      };
164→    } catch (error) {
165→      this.logger.warn(
166→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
167→      );
168→      throw new UnauthorizedException('Invalid CipherBox identity token');
169→    }
170→  }
171→
172→  async refresh(
173→    refreshToken: string,
174→    userId: string,
175→    publicKey: string
176→  ): Promise<RefreshServiceResult> {
177→    const tokens = await this.tokenService.rotateRefreshToken(refreshToken, userId, publicKey);
178→
179→    return {
180→      accessToken: tokens.accessToken,
181→      refreshToken: tokens.refreshToken,
182→    };
183→  }
184→
185→  async logout(userId: string): Promise<LogoutResponseDto> {
186→    await this.tokenService.revokeAllUserTokens(userId);
187→    return { success: true };
188→  }
189→
190→  /**
191→   * Refresh tokens by searching for the matching refresh token across all users.
192→   * This allows refresh without requiring the (possibly expired) access token.
193→   */
194→  async refreshByToken(refreshToken: string): Promise<RefreshServiceResult> {
195→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
196→    const prefix = refreshToken.substring(0, 16);
197→    const tokens = await this.refreshTokenRepository.find({
198→      where: {
199→        tokenPrefix: prefix,
200→        revokedAt: IsNull(),
201→      },
202→      relations: ['user'],
203→    });
204→
205→    // Find matching token by verifying against hashes
206→    let validToken: RefreshToken | null = null;
207→    for (const token of tokens) {
208→      // Skip expired tokens
209→      if (token.expiresAt < new Date()) {
210→        continue;
211→      }
212→      try {
213→        if (await argon2.verify(token.tokenHash, refreshToken)) {
214→          validToken = token;
215→          break;
216→        }
217→      } catch {
218→        // argon2.verify throws on invalid hash format, continue checking
219→        continue;
220→      }
221→    }
222→
223→    if (!validToken) {
224→      throw new UnauthorizedException('Invalid or expired refresh token');
225→    }
226→
227→    // Revoke old token
228→    validToken.revokedAt = new Date();
229→    await this.refreshTokenRepository.save(validToken);
230→
231→    // Create new tokens
232→    const newTokens = await this.tokenService.createTokens(
233→      validToken.userId,
234→      validToken.user.publicKey
235→    );
236→
237→    // Look up user's email from their most recently used auth method
238→    // (covers both email and google auth methods)
239→    const emailMethod = await this.authMethodRepository.findOne({
240→      where: [
241→        { userId: validToken.userId, type: 'email' },
242→        { userId: validToken.userId, type: 'google' },
243→      ],
244→      order: { lastUsedAt: 'DESC' },
245→    });
246→
247→    return {
248→      accessToken: newTokens.accessToken,
249→      refreshToken: newTokens.refreshToken,
250→      // H-09: Fall back to undefined instead of leaking raw identifier hash
251→      email: emailMethod?.identifierDisplay || undefined,
252→    };
253→  }
254→
255→  /**
256→   * Get all linked auth methods for a user.
257→   * Returns identifierDisplay (human-readable) for all method types.
258→   * Falls back to identifier if identifierDisplay is not set.
259→   */
260→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
261→    const methods = await this.authMethodRepository.find({
262→      where: { userId },
263→      order: { createdAt: 'ASC' },
264→    });
265→
266→    return methods.map((method) => ({
267→      id: method.id,
268→      type: method.type,
269→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
270→      identifier: method.identifierDisplay || '[redacted]',
271→      lastUsedAt: method.lastUsedAt,
272→      createdAt: method.createdAt,
273→    }));
274→  }
275→
276→  /**
277→   * Link a new auth method to an existing user account.
278→   *
279→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
280→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
281→   *
282→   * Cross-account collision: if the auth method already belongs to a different user,
283→   * a BadRequestException is thrown (user must unlink from the other account first).
284→   */
285→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
286→    // 1. Get the user
287→    const user = await this.userRepository.findOne({ where: { id: userId } });
288→    if (!user) {
289→      throw new UnauthorizedException('User not found');
290→    }
291→
292→    const authMethodType = linkDto.loginType;
293→
294→    if (authMethodType === 'wallet') {
295→      // Wallet linking: verify SIWE message + signature
296→      return this.linkWalletMethod(userId, linkDto);
297→    }
298→
299→    // Google/email linking: verify CipherBox-issued JWT
300→    return this.linkJwtMethod(userId, linkDto);
301→  }
