303→  /**
304→   * Link a Google or email auth method via CipherBox JWT verification.
305→   */
306→  private async linkJwtMethod(
307→    userId: string,
308→    linkDto: LinkMethodDto
309→  ): Promise<AuthMethodResponseDto[]> {
310→    // 1. Verify the CipherBox-issued JWT
311→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
312→
313→    // 2. Determine type and identifier, hash for lookup
314→    const authMethodType = linkDto.loginType;
315→    const identifier = payload.email || payload.sub;
316→    if (!identifier) {
317→      throw new BadRequestException('Cannot determine identifier from JWT');
318→    }
319→    const identifierHash = this.siweService.hashIdentifier(identifier);
320→
321→    // 3. Check cross-account collision: same identifier linked to a different user
322→    const crossAccountMethod = await this.authMethodRepository.findOne({
323→      where: {
324→        type: authMethodType,
325→        identifierHash,
326→        userId: Not(userId),
327→      },
328→    });
329→
330→    if (crossAccountMethod) {
331→      throw new BadRequestException(
332→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
333→      );
334→    }
335→
336→    // 4. Check if this exact method is already linked to this user
337→    const existingMethod = await this.authMethodRepository.findOne({
338→      where: {
339→        userId,
340→        type: authMethodType,
341→        identifierHash,
342→      },
343→    });
344→
345→    if (existingMethod) {
346→      throw new BadRequestException('This auth method is already linked to your account');
347→    }
348→
349→    // 5. Create new AuthMethod entity with hashed identifier
350→    await this.authMethodRepository.save({
351→      userId,
352→      type: authMethodType,
353→      identifier: identifierHash,
354→      identifierHash,
355→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
356→      lastUsedAt: new Date(),
357→    });
358→
359→    // 6. Return updated list of methods
360→    return this.getLinkedMethods(userId);
361→  }
