477→  /**
478→   * Test-only login that bypasses Core Kit entirely.
479→   * Guarded by TEST_LOGIN_SECRET env var — never available in production.
480→   *
481→   * Creates/finds user by email, generates a deterministic secp256k1 keypair,
482→   * and issues tokens. Returns the keypair so E2E tests can initialize vaults.
483→   */
484→  async testLogin(
485→    email: string,
486→    secret: string
487→  ): Promise<{
488→    accessToken: string;
489→    refreshToken: string;
490→    isNewUser: boolean;
491→    publicKeyHex: string;
492→    privateKeyHex: string;
493→  }> {
494→    // 1. Defense-in-depth: never allow in production regardless of env var
495→    const nodeEnv = this.configService.get<string>('NODE_ENV');
496→    if (nodeEnv === 'production') {
497→      throw new ForbiddenException('Test login is not available in production');
498→    }
499→
500→    // 2. Validate TEST_LOGIN_SECRET with timing-safe comparison
501→    const expectedSecret = this.configService.get<string>('TEST_LOGIN_SECRET');
502→    if (!expectedSecret) {
503→      throw new ForbiddenException('Test login is not enabled');
504→    }
505→    const secretBuf = Buffer.from(secret);
506→    const expectedBuf = Buffer.from(expectedSecret);
507→    if (secretBuf.length !== expectedBuf.length || !timingSafeEqual(secretBuf, expectedBuf)) {
508→      throw new UnauthorizedException('Invalid test login secret');
509→    }
510→
511→    // 2. Generate deterministic secp256k1 keypair from email
512→    const { publicKeyHex, privateKeyHex } = this.generateDeterministicKeypair(email);
513→
514→    // 3. Find or create user by email (hash-based lookup)
515→    const normalizedEmail = email.toLowerCase().trim();
516→    const identifierHash = this.siweService.hashIdentifier(normalizedEmail);
517→
518→    const existingMethod = await this.authMethodRepository.findOne({
519→      where: { type: 'email', identifierHash },
520→      relations: ['user'],
521→    });
522→
523→    let user: User;
524→    let isNewUser = false;
525→
526→    if (existingMethod) {
527→      user = existingMethod.user;
528→      // Update publicKey to match deterministic keypair (may differ from Core Kit key)
529→      if (user.publicKey !== publicKeyHex) {
530→        user.publicKey = publicKeyHex;
531→        await this.userRepository.save(user);
532→      }
533→      existingMethod.lastUsedAt = new Date();
534→      await this.authMethodRepository.save(existingMethod);
535→    } else {
536→      isNewUser = true;
537→      user = await this.userRepository.save({ publicKey: publicKeyHex });
538→      await this.authMethodRepository.save({
539→        userId: user.id,
540→        type: 'email',
541→        identifier: identifierHash,
542→        identifierHash,
543→        identifierDisplay: this.siweService.truncateEmail(normalizedEmail),
544→        lastUsedAt: new Date(),
545→      });
546→    }
547→
548→    // 4. Issue tokens
549→    const tokens = await this.tokenService.createTokens(user.id, user.publicKey);
550→
551→    this.logger.log(`Test login: userId=${user.id}, isNew=${isNewUser}`);
552→
553→    return {
554→      accessToken: tokens.accessToken,
555→      refreshToken: tokens.refreshToken,
556→      isNewUser,
557→      publicKeyHex,
558→      privateKeyHex,
559→    };
560→  }
561→
562→  /**
563→   * Generate a deterministic secp256k1 keypair from an email address.
564→   * Same email always produces the same keypair, enabling consistent
565→   * vault encryption across test runs.
566→   */
567→  private generateDeterministicKeypair(email: string): {
568→    publicKeyHex: string;
569→    privateKeyHex: string;
570→  } {
571→    // Derive 32-byte private key from email via SHA-256
572→    const seed = createHash('sha256')
573→      .update(`cipherbox-test-keypair:${email.toLowerCase().trim()}`)
574→      .digest();
575→
576→    // Ensure the seed is a valid secp256k1 private key (must be in [1, n-1])
577→    const n = BigInt('0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141');
578→    let keyInt = BigInt('0x' + seed.toString('hex'));
579→    keyInt = (keyInt % (n - 1n)) + 1n;
580→    const privateKeyHex = keyInt.toString(16).padStart(64, '0');
581→
582→    const ecdh = createECDH('secp256k1');
583→    ecdh.setPrivateKey(Buffer.from(privateKeyHex, 'hex'));
584→    const publicKeyHex = ecdh.getPublicKey().toString('hex'); // 65 bytes uncompressed
585→
586→    return { publicKeyHex, privateKeyHex };
587→  }
588→}
