 65→    @Body() loginDto: LoginDto,
 66→    @Req() req: ExpressRequest,
 67→    @Res({ passthrough: true }) res: Response
 68→  ): Promise<LoginResponseDto> {
 69→    const result = await this.authService.login(loginDto);
 70→    this.metricsService.authLogins.inc({
 71→      method: 'web3auth',
 72→      new_user: String(result.isNewUser),
 73→    });
 74→    const isDesktop = req.headers['x-client-type'] === 'desktop';
 75→
 76→    if (isDesktop) {
 77→      // Desktop clients: return refreshToken in response body (no cookie)
 78→      return {
 79→        accessToken: result.accessToken,
 80→        refreshToken: result.refreshToken,
 81→        isNewUser: result.isNewUser,
 82→      };
 83→    }
 84→
 85→    // Web clients: set refresh token in HTTP-only cookie
 86→    res.cookie('refresh_token', result.refreshToken, REFRESH_TOKEN_COOKIE_OPTIONS);
