144→  /**
145→   * Verify a CipherBox-issued JWT for Core Kit login flow.
146→   * Since we are the identity provider, we verify against our own JWKS.
147→   */
148→  private async verifyCipherBoxJwt(
149→    idToken: string
150→  ): Promise<{ sub?: string; verifierId?: string; email?: string }> {
151→    try {
152→      const jwksData = this.jwtIssuerService.getJwksData();
153→      const jwks = jose.createLocalJWKSet(jwksData);
154→      const { payload } = await jose.jwtVerify(idToken, jwks, {
155→        issuer: 'cipherbox',
156→        audience: 'web3auth',
157→        algorithms: ['RS256'],
158→      });
159→      return {
160→        sub: payload.sub,
161→        verifierId: payload.sub,
162→        email: payload.email as string | undefined,
163→      };
164→    } catch (error) {
165→      this.logger.warn(
166→        `CipherBox JWT verification failed: ${error instanceof Error ? error.message : 'unknown'}`
167→      );
168→      throw new UnauthorizedException('Invalid CipherBox identity token');
169→    }
170→  }
171→
172→  async refresh(
173→    refreshToken: string,
174→    userId: string,
175→    publicKey: string
176→  ): Promise<RefreshServiceResult> {
177→    const tokens = await this.tokenService.rotateRefreshToken(refreshToken, userId, publicKey);
178→
179→    return {
180→      accessToken: tokens.accessToken,
181→      refreshToken: tokens.refreshToken,
182→    };
183→  }
184→
185→  async logout(userId: string): Promise<LogoutResponseDto> {
186→    await this.tokenService.revokeAllUserTokens(userId);
187→    return { success: true };
188→  }
189→
190→  /**
191→   * Refresh tokens by searching for the matching refresh token across all users.
192→   * This allows refresh without requiring the (possibly expired) access token.
193→   */
194→  async refreshByToken(refreshToken: string): Promise<RefreshServiceResult> {
195→    // Find candidate tokens by prefix for O(1) lookup instead of O(N) Argon2 scan
196→    const prefix = refreshToken.substring(0, 16);
197→    const tokens = await this.refreshTokenRepository.find({
198→      where: {
199→        tokenPrefix: prefix,
200→        revokedAt: IsNull(),
201→      },
202→      relations: ['user'],
203→    });
204→
205→    // Find matching token by verifying against hashes
206→    let validToken: RefreshToken | null = null;
207→    for (const token of tokens) {
208→      // Skip expired tokens
209→      if (token.expiresAt < new Date()) {
210→        continue;
211→      }
212→      try {
213→        if (await argon2.verify(token.tokenHash, refreshToken)) {
214→          validToken = token;
215→          break;
216→        }
217→      } catch {
218→        // argon2.verify throws on invalid hash format, continue checking
219→        continue;
220→      }
221→    }
222→
223→    if (!validToken) {
224→      throw new UnauthorizedException('Invalid or expired refresh token');
225→    }
226→
227→    // Revoke old token
228→    validToken.revokedAt = new Date();
229→    await this.refreshTokenRepository.save(validToken);
230→
231→    // Create new tokens
232→    const newTokens = await this.tokenService.createTokens(
233→      validToken.userId,
234→      validToken.user.publicKey
235→    );
236→
237→    // Look up user's email from their most recently used auth method
238→    // (covers both email and google auth methods)
239→    const emailMethod = await this.authMethodRepository.findOne({
240→      where: [
241→        { userId: validToken.userId, type: 'email' },
242→        { userId: validToken.userId, type: 'google' },
243→      ],
244→      order: { lastUsedAt: 'DESC' },
245→    });
246→
247→    return {
248→      accessToken: newTokens.accessToken,
249→      refreshToken: newTokens.refreshToken,
250→      // H-09: Fall back to undefined instead of leaking raw identifier hash
251→      email: emailMethod?.identifierDisplay || undefined,
252→    };
253→  }
254→
255→  /**
256→   * Get all linked auth methods for a user.
257→   * Returns identifierDisplay (human-readable) for all method types.
258→   * Falls back to identifier if identifierDisplay is not set.
259→   */
260→  async getLinkedMethods(userId: string): Promise<AuthMethodResponseDto[]> {
261→    const methods = await this.authMethodRepository.find({
262→      where: { userId },
263→      order: { createdAt: 'ASC' },
264→    });
265→
266→    return methods.map((method) => ({
267→      id: method.id,
268→      type: method.type,
269→      // H-09: Fall back to '[redacted]' instead of leaking raw identifier hash
270→      identifier: method.identifierDisplay || '[redacted]',
271→      lastUsedAt: method.lastUsedAt,
272→      createdAt: method.createdAt,
273→    }));
274→  }
275→
276→  /**
277→   * Link a new auth method to an existing user account.
278→   *
279→   * For Google/email: verifies CipherBox-issued JWT to confirm ownership of the new method.
280→   * For wallet: verifies SIWE message+signature to confirm wallet ownership.
281→   *
282→   * Cross-account collision: if the auth method already belongs to a different user,
283→   * a BadRequestException is thrown (user must unlink from the other account first).
284→   */
285→  async linkMethod(userId: string, linkDto: LinkMethodDto): Promise<AuthMethodResponseDto[]> {
286→    // 1. Get the user
287→    const user = await this.userRepository.findOne({ where: { id: userId } });
288→    if (!user) {
289→      throw new UnauthorizedException('User not found');
290→    }
291→
292→    const authMethodType = linkDto.loginType;
293→
294→    if (authMethodType === 'wallet') {
295→      // Wallet linking: verify SIWE message + signature
296→      return this.linkWalletMethod(userId, linkDto);
297→    }
298→
299→    // Google/email linking: verify CipherBox-issued JWT
300→    return this.linkJwtMethod(userId, linkDto);
301→  }
302→
303→  /**
304→   * Link a Google or email auth method via CipherBox JWT verification.
305→   */
306→  private async linkJwtMethod(
307→    userId: string,
308→    linkDto: LinkMethodDto
309→  ): Promise<AuthMethodResponseDto[]> {
310→    // 1. Verify the CipherBox-issued JWT
311→    const payload = await this.verifyCipherBoxJwt(linkDto.idToken);
312→
313→    // 2. Determine type and identifier, hash for lookup
314→    const authMethodType = linkDto.loginType;
315→    const identifier = payload.email || payload.sub;
316→    if (!identifier) {
317→      throw new BadRequestException('Cannot determine identifier from JWT');
318→    }
319→    const identifierHash = this.siweService.hashIdentifier(identifier);
320→
321→    // 3. Check cross-account collision: same identifier linked to a different user
322→    const crossAccountMethod = await this.authMethodRepository.findOne({
323→      where: {
324→        type: authMethodType,
325→        identifierHash,
326→        userId: Not(userId),
327→      },
328→    });
329→
330→    if (crossAccountMethod) {
331→      throw new BadRequestException(
332→        `This ${authMethodType === 'google' ? 'Google account' : 'email'} is already linked to another account`
333→      );
334→    }
335→
336→    // 4. Check if this exact method is already linked to this user
337→    const existingMethod = await this.authMethodRepository.findOne({
338→      where: {
339→        userId,
340→        type: authMethodType,
341→        identifierHash,
342→      },
343→    });
344→
345→    if (existingMethod) {
346→      throw new BadRequestException('This auth method is already linked to your account');
347→    }
348→
349→    // 5. Create new AuthMethod entity with hashed identifier
350→    await this.authMethodRepository.save({
351→      userId,
352→      type: authMethodType,
353→      identifier: identifierHash,
354→      identifierHash,
355→      identifierDisplay: payload.email ? this.siweService.truncateEmail(payload.email) : identifier,
356→      lastUsedAt: new Date(),
357→    });
358→
359→    // 6. Return updated list of methods
360→    return this.getLinkedMethods(userId);
361→  }
362→
363→  /**
364→   * Link a wallet auth method via SIWE verification.
365→   */
366→  private async linkWalletMethod(
367→    userId: string,
368→    linkDto: LinkMethodDto
369→  ): Promise<AuthMethodResponseDto[]> {
370→    // 1. Validate required SIWE fields
371→    if (!linkDto.walletAddress || !linkDto.siweMessage || !linkDto.siweSignature) {
372→      throw new BadRequestException(
373→        'walletAddress, siweMessage, and siweSignature are required for wallet linking'
374→      );
375→    }
376→
377→    // 2. Verify SIWE signature with nonce consumption (C-01: prevent replay)
378→    const domain = this.configService.get<string>('SIWE_DOMAIN', 'localhost');
379→    const parsed = parseSiweMessage(linkDto.siweMessage);
380→    if (!parsed.nonce) {
381→      throw new BadRequestException('Invalid SIWE message: missing nonce');
382→    }
383→
384→    // Consume nonce from Redis (single-use) — same pattern as identity.controller.ts walletLogin
385→    const nonceKey = `siwe:nonce:${parsed.nonce}`;
386→    let nonceDeleted: number;
387→    try {
388→      nonceDeleted = await this.redis.del(nonceKey);
389→    } catch (err) {
390→      this.logger.error('Redis error during nonce consumption', err);
391→      throw new BadRequestException('Nonce verification failed');
392→    }
393→    if (!nonceDeleted) {
394→      throw new BadRequestException('Invalid or expired nonce');
395→    }
396→
397→    const walletAddress = await this.siweService.verifySiweMessage(
398→      linkDto.siweMessage,
399→      linkDto.siweSignature as `0x${string}`,
400→      parsed.nonce,
401→      domain
402→    );
403→
404→    // 3. Hash the wallet address for lookup
405→    const addressHash = this.siweService.hashWalletAddress(walletAddress);
406→
407→    // 4. Check cross-account collision: same wallet linked to a different user
408→    const crossAccountMethod = await this.authMethodRepository.findOne({
409→      where: {
410→        type: 'wallet',
411→        identifierHash: addressHash,
412→        userId: Not(userId),
413→      },
414→    });
415→
416→    if (crossAccountMethod) {
417→      throw new BadRequestException('This wallet is already linked to another account');
418→    }
419→
420→    // 5. Check if this wallet is already linked to this user
421→    const existingMethod = await this.authMethodRepository.findOne({
422→      where: {
423→        userId,
424→        type: 'wallet',
425→        identifierHash: addressHash,
426→      },
427→    });
428→
429→    if (existingMethod) {
430→      throw new BadRequestException('This wallet is already linked to your account');
431→    }
432→
433→    // 6. Create wallet auth method with hash + truncated display
434→    const truncated = this.siweService.truncateWalletAddress(walletAddress);
435→    await this.authMethodRepository.save({
436→      userId,
437→      type: 'wallet',
438→      identifier: addressHash,
439→      identifierHash: addressHash,
440→      identifierDisplay: truncated,
441→      lastUsedAt: new Date(),
442→    });
443→
444→    // 7. Return updated list of methods
445→    return this.getLinkedMethods(userId);
446→  }
447→
448→  /**
449→   * Unlink an auth method from a user account.
450→   * Cannot unlink the last remaining auth method.
451→   */
452→  async unlinkMethod(userId: string, methodId: string): Promise<void> {
453→    await this.authMethodRepository.manager.transaction(async (manager) => {
454→      // 1. Lock all auth methods for this user to prevent concurrent unlinks
455→      const methods = await manager
456→        .createQueryBuilder(AuthMethod, 'am')
457→        .setLock('pessimistic_write')
458→        .where('am.userId = :userId', { userId })
459→        .getMany();
460→
461→      // 2. Find the target method
462→      const method = methods.find((m) => m.id === methodId);
463→      if (!method) {
464→        throw new BadRequestException('Auth method not found');
465→      }
466→
467→      // 3. Cannot unlink if only 1 method remains
468→      if (methods.length <= 1) {
469→        throw new BadRequestException('Cannot unlink your last auth method');
470→      }
471→
472→      // 4. Delete the method
473→      await manager.remove(method);
474→    });
475→  }
